export interface Device {
  /** Its owner's app says it starts with the computer and works at the
   * lock screen (`None`: not said). */
  anytime?: boolean | null;
  /** The GaiaDesk version it last registered with (the server's list only). */
  app_version?: string | null;
  /** The desk is offline but holds a doorbell socket: it can be woken. */
  asleep?: boolean;
  desk_id: string;
  /** Free space on the desk's system volume, in MB. Only with `--probe`
   * (the desk reports it; an older desk or an unreached one: absent). */
  free_disk_mb?: number | null;
  /** The last one that failed, and why. */
  last_failure?: ReachFailure | null;
  /** The last connect from this machine that worked (`cli_reach`). */
  last_ok?: ReachSuccess | null;
  /** Seconds since the epoch. */
  last_seen?: number | null;
  name?: string | null;
  /** `Some(true)` online, `Some(false)` offline, `None` unknown. */
  online?: boolean | null;
  os?: string | null;
  /** Whose desk: "you", a teammate's email, or unknown. */
  owner?: string | null;
  probe?: ProbeResult | null;
  /** Reachable NOW: only with `--probe` (else `null`). */
  reachable?: boolean | null;
  /** Seconds since the server last heard the desk's socket (online desks,
   * a server that says). Long silence on an "online" desk: a dead socket. */
  signal_idle_secs?: number | null;
  /** Where this desk was found: "account", "team", "lan" (seen on this
   * network just now), "pinned" (paired over the LAN before, not seen on
   * this network now), "mesh", "recent". */
  sources: Array<string>;
  /** What a script branches on: "online", "asleep" (offline, but it holds
   * a doorbell socket so `wake` will bring it up), "offline" or
   * "unknown". With `last_seen` it answers "is it worth waiting for". */
  state?: string;
}

/** `devices --json`. */
export interface DeviceList {
  devices: Array<Device>;
  /** Who this machine is signed in as, and where that came from — the
   * account whose desks the server listed. */
  identity: Identity;
  notes: Array<string>;
  /** Which sources answered: `server`, `lan`, `mesh`, `recent`. */
  sources: Array<string>;
}

/** One volume in `DeskStats`. */
export interface DiskStat {
  free_mb: number;
  /** Where it is mounted (`/`, `C:\\`). */
  mount: string;
  total_mb: number;
}

/** Why a call did not succeed: one of six `ErrorKind`s, a sentence for a
 * person, the finer cause where there is one, and the desk it concerned.
 * 
 * Its serde form is the object inside `gaiadesk-cli`'s `--json` error
 * envelope (`ErrorEnvelope`): `{"kind", "message", "reason"?, "desk"?}`. */
export interface Error {
  /** The desk it concerned, when there was one. */
  desk?: string | null;
  kind: ErrorKind;
  message: string;
  /** The finer cause: `offline`, `unknown_desk`, `not_online`, `network`,
   * `not_signed_in`, `timeout`, `local`, … */
  reason?: string | null;
}

/** The six kinds a program branches on. Stable: a new kind would be a
 * breaking change, so match with a wildcard arm anyway. */
export type ErrorKind = "usage" | "refused" | "unreachable" | "connection_lost" | "failed" | "protocol";

/** One event of a streamed command (`Desk::exec_stream`) —
 * `gaiadesk-cli exec --json-stream` prints one per line (all but `note`). */
export type ExecEvent = {
  data: string;
  event: "stdout";
} | {
  data: string;
  event: "stderr";
} | {
  event: "note";
  message: string;
} | ExecExit | {
  error: Error;
  event: "error";
  exit: number;
};

/** `ExecResult` without the output — the last event of a stream. */
export interface ExecExit {
  desk: string;
  duration_ms: number;
  error?: Error | null;
  exit: number;
  mode?: string | null;
  notes: Array<string>;
  remote_code?: number | null;
  route?: string | null;
  shell?: string | null;
  timed_out: boolean;
}

/** How one command ended — `gaiadesk-cli exec --json`'s object. */
export interface ExecResult {
  desk: string;
  duration_ms: number;
  /** `null` when it ran and ended on its own. */
  error?: Error | null;
  /** What `gaiadesk-cli exec` exits with: the program's code (0-255), 124
   * timed out, 130 interrupted, 254 refused, 255 not reached. */
  exit: number;
  /** `pipes`, or `terminal` on a desk from before plain pipes. */
  mode?: string | null;
  /** This client's own lines about the run. */
  notes: Array<string>;
  /** The program's own code (`null`: it never ran). */
  remote_code?: number | null;
  /** `LAN`, `Mesh`, `the GaiaDesk server` (`null`: never reached). */
  route?: string | null;
  /** The shell the desk actually used (`null`: it did not say). */
  shell?: string | null;
  stderr: string;
  stdout: string;
  timed_out: boolean;
  /** More than 16 MB of a stream was dropped. */
  truncated: boolean;
}

/** One command to run on a desk (`Desk::exec`).
 * 
 * `command` is ONE command line, given to the shell verbatim; `argv` is an
 * argument vector, each entry quoted for the shell so the program receives
 * exactly it. Build it with `ExecSpec::command` or `ExecSpec::argv`. */
export interface ExecSpec {
  /** Run it as administrator (root / SYSTEM): an `admin`-scoped token and the desk
   * owner's Admin access; else refused (`reason` `admin_*`, docs/admin-access.md). */
  admin?: boolean;
  argv?: Array<string>;
  command?: string | null;
  /** The directory it starts in on the desk (relative: from the desk
   * user's home, or a confined token's directory). */
  cwd?: string | null;
  /** Environment variables for it, on top of the desk's (sent in the
   * request, never logged). */
  env?: Record<string, string>;
  /** Kill the process tree when the caller disconnects (`exec --kill-tree-on-disconnect`).
   * Without this, the process keeps running after the client exits. */
  kill_on_disconnect?: boolean;
  shell?: Shell;
  /** Text for its stdin, then end of input. Absent: stdin is closed (the
   * null device), unless `crate::ExecInput` feeds it. */
  stdin?: string | null;
  /** Stop it after this many seconds (`0`: no limit; absent: 30 minutes). */
  timeout_secs?: number | null;
}

/** `whoami --json`; `devices --json`'s `identity`. */
export interface Identity {
  /** The account's email (`null`: not signed in, or the server could not
   * say). */
  account?: string | null;
  /** `app`, `login`, `token` or `none`; from the hosted API (`GET
   * /v1/desks`), `api_key` or `session`. */
  source: string;
}

/** A background job on a desk. */
export interface Job {
  /** Who started it: the token's name, or `owner` for a person. */
  by?: string;
  command: string;
  ended_at_ms?: number | null;
  /** How the desk enforces them, one line each, in its own words — and
   * what it could not do here (e.g. "cgroups v2 not available: …"). */
  enforcement?: Array<string>;
  exit_code?: number | null;
  /** The caps and keep-awake it runs under, as the desk applied them
   * (`keep_awake` resolved against the desk's default). `None` from a desk
   * before job limits, and for a job started with none. */
  limits?: JobLimits | null;
  /** Bytes of output kept (current log plus its one rotated predecessor). */
  log_bytes?: number;
  /** The desk's limit on jobs running at once; a job past it waits in state
   * `queued`. Absent from a desk before queueing. */
  max_running?: number | null;
  name: string;
  pid?: number | null;
  /** 1-based place in the queue while `state` is `queued`. */
  queue_position?: number | null;
  /** Why it ended as it did, as a machine reads it, when the desk knows:
   * `blocked_by_os_policy` — Windows Smart App Control or WDAC refused
   * to start a program it ran (its `state` then says so in words). */
  reason?: string | null;
  started_at_ms: number;
  /** `queued` (waiting for a free slot), `running`, `exited`, `killed`, or `lost` (it was running when the
   * GaiaDesk host restarted and its end could not be observed). */
  state: string;
}

/** What a background job may use, and whether the desk stays awake for it
 * (`DataMessage::JobStart`'s `limits`). Every field optional and
 * off the wire when unset, so a start without limits is byte for byte what
 * it was. A desk lists `feature::JOB_LIMITS` when it enforces them;
 * a desk before that ignores the field, which is why a CLI refuses to send
 * caps to one. */
export interface JobLimits {
  /** At most this share of the whole machine's CPU, 1–100. */
  cpu_percent?: number | null;
  /** Hold off idle sleep while the job runs. `None`: the desk's default. */
  keep_awake?: boolean | null;
  /** Stop the job (its whole process tree) after this many seconds of
   * running (`run --max-runtime`); it ends `killed (max runtime exceeded)`. */
  max_runtime_secs?: number | null;
  /** At most this much memory for the job and everything it starts, MB. */
  mem_mb?: number | null;
  /** `low`, `normal` or `high`. */
  priority?: string | null;
}

/** `ps --json`. */
export interface JobList {
  jobs: Array<Job>;
}

/** One event of a followed job's output (`logs -f --json`). */
export type JobLogEvent = {
  data: string;
  event: "output";
} | {
  event: "end";
  job: Job;
} | {
  event: "interrupted";
} | {
  error: Error;
  event: "error";
};

/** `logs --json`: a job and the end of its output. */
export interface JobLogs {
  job: Job;
  output: string;
}

/** A background job to start (`Desk::run_job`). */
export interface JobSpec {
  /** ONE entry is the command line, verbatim for the desk's shell (`sh -c`,
   * `cmd /c`); several are words, each quoted for THAT desk's shell. */
  command: Array<string>;
  cwd?: string | null;
  /** Environment variables for it (never logged). */
  env?: Record<string, string>;
  limits?: JobLimits;
  /** Letters, digits, `.`, `_`, `-`: how `jobs`, `job_logs` and `kill_job`
   * find it. */
  name: string;
  /** The shell that runs it (absent: the desk's job shell — `sh -c`,
   * `cmd /c`). `none` is not one: a job is a command line. */
  shell?: Shell | null;
}

/** How a wait for a job ended (`Desk::wait_job`): the job as it
 * ended — or, `timed_out`, as it stands, still running. (`gaiadesk-cli
 * wait --json` prints `job`.) */
export interface JobWaitResult {
  job: Job;
  timed_out: boolean;
}

/** `token create --json` (several desks: one token each). */
export interface MintResult {
  tokens: Array<MintedToken>;
}

/** An agent token to mint (`Desk::mint_token`). */
export interface MintSpec {
  /** The directory on the desk the token's work is confined to. */
  cwd?: string | null;
  expires_secs: number;
  /** Its work runs as the desk's low-privilege agent user. */
  low_priv?: boolean;
  name: string;
  /** `exec`, `shell`, `cp`, `forward`, `jobs`, `screen`, `admin` (never implied). */
  scopes: Array<string>;
}

/** One minted token. `secret` is the token itself — shown once. */
export interface MintedToken {
  desk: string;
  secret: string;
  token: TokenInfo;
}

/** One desk's probe. */
export interface ProbeResult {
  connect_ms?: number | null;
  /** Whether it was dialled at all (no credential for it: not). */
  dialled: boolean;
  error?: string | null;
  /** Free MB on the desk's system volume (the desk's own report). */
  free_disk_mb?: number | null;
  hostname?: string | null;
  /** Why not: a `dial_stage::kind`, an error kind,
   * `agent_not_answering` or `no_credential`. */
  kind?: string | null;
  /** Connected AND its agent answered a round trip. */
  ok: boolean;
  os?: string | null;
  route?: string | null;
  rtt_ms?: number | null;
}

/** A connect that did not. */
export interface ReachFailure {
  at: number;
  /** A stable key: a `dial_stage::kind` or an error kind. */
  kind: string;
  /** One line, as the CLI said it. */
  message: string;
}

/** A connect that worked. */
export interface ReachSuccess {
  /** Seconds since the epoch. */
  at: number;
  /** How long the connect took, ms. */
  connect_ms?: number | null;
  /** `LAN`, `Mesh`, `the GaiaDesk server`. */
  route: string;
  /** A data-plane round trip measured on it (`devices --probe`), ms. */
  rtt_ms?: number | null;
}

/** `token revoke --json`. */
export interface Revoked {
  revoked: string;
  stopped_sessions: number;
}

/** Which shell runs a command on the desk. */
export type Shell = "default" | "none" | "sh" | "bash" | "zsh" | "cmd" | "pwsh" | "powershell";

/** `stats --json`: the desk's own figures. */
export interface StatsReport {
  /** Busy share of the whole machine, 0–100, over a short sample. */
  cpu_percent: number;
  /** Logical CPUs. */
  cpus: number;
  desk: string;
  /** Every mounted volume worth listing, with its free space. */
  disks?: Array<DiskStat>;
  hostname: string;
  /** Background jobs (`gaiadesk-cli run --detach`) running now. */
  jobs_running: number;
  /** When the OS last booted, RFC 3339 UTC (computed from uptime on host). */
  last_reboot_utc?: string | null;
  /** 1, 5 and 15 minute load averages. `None` where the OS has none (Windows). */
  load?: Array<number> | null;
  /** The account running the host process (the logged-in user for a user-mode agent). */
  logged_user?: string | null;
  /** What programs can still have without swapping ("available"). */
  mem_free_mb: number;
  /** macOS memory pressure: `normal`, `warn` or `critical`. */
  mem_pressure?: string | null;
  mem_total_mb: number;
  /** `macos`, `windows`, `linux` (`std::env::consts::OS`). */
  os: string;
  /** The OS's own name and version (`macOS 15.1`, `Windows 11 (26100)`). */
  os_version?: string;
  /** Swap (macOS `vm.swapusage`, Linux `/proc/meminfo`, Windows the page
   * file), when the desk says: its size now and how much is in use. */
  swap_total_mb?: number | null;
  swap_used_mb?: number | null;
  uptime_secs: number;
}

/** One agent token as its desk's owner sees it: everything but the secret. */
export interface TokenInfo {
  /** The directory this token's work is confined to: its commands, shells
   * and jobs start there, and every path it copies must resolve inside it
   * (links resolved first). `None`: not confined. */
  cwd?: string | null;
  expires_at_ms: number;
  /** The token's non-secret id (a digest of its stored hash). */
  id: string;
  issued_at_ms: number;
  label: string;
  last_used_ms?: number | null;
  /** Its commands, shells and jobs run as the desk's low-privilege agent
   * user (set on the desk), or are refused — never as the desk's own user. */
  low_priv?: boolean;
  revoked?: boolean;
  /** What it may do: `screen`, `exec`, `shell`, `cp`, `forward`, `jobs`,
   * `admin` (ask to run as administrator — never implied). Empty for a
   * token from before scopes, which is a screen (Agent Access) token. */
  scopes?: Array<string>;
}

/** `token list --json`. */
export interface TokenList {
  tokens: Array<TokenInfo>;
}

export interface GetDeskReachQuery {
  /** Unix seconds. Default seven days ago; the log keeps thirty. */
  since?: number;
  /** At most this many transitions, newest first (default 200, at most 1000). */
  limit?: number;
}

export interface ListAuditQuery {
  /** Only events about this desk (one of the caller's own). */
  desk?: string;
  /** Only events by this actor id (an email, a token id). */
  actor?: string;
  /** Only this action, or every action under it when it ends in `.*` (`api.*`). */
  action?: string;
  /** Only events by this agent token id or API key id. */
  token?: string;
  since_ms?: number;
  until_ms?: number;
  /** At most this many (default 100, at most 500). */
  limit?: number;
}

export interface ListSupportSessionsQuery {
  state?: "open" | "all" | "waiting" | "joined" | "ended" | "expired";
  /** Only sessions created after this Unix time (seconds). */
  created_after?: number;
  /** Only sessions created before this Unix time (seconds). */
  created_before?: number;
  /** Only sessions created with this `external_id`. */
  external_id?: string;
  /** A person's list: `true` (default) for live sessions, `false` for test ones. An API key lists only its own mode and may leave this out. */
  livemode?: "true" | "false";
  /** At most this many (default 50, at most 200). */
  limit?: number;
}

export interface ExecOnDeskQuery {
  /** `1`: answer Server-Sent Events. */
  stream?: 0 | 1;
}

export interface JobLogsQuery {
  follow?: 0 | 1;
  /** The last this many bytes (default all the desk keeps). */
  tail?: number;
}

export interface WaitJobQuery {
  /** Give up after this many seconds and answer the job as it stands (default and at most 870; `0` answers at once). */
  timeout?: number;
}
